package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertJobRecords.*;
import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.*;
public final class HttpAlertTaskClient implements AlertTaskClient {
 private final String market,notification;private final AlertTaskHttp http;private final Duration executeTimeout,readTimeout;
 public HttpAlertTaskClient(String market,String notification,String token,ObjectMapper mapper){this(market,notification,token,mapper,Duration.ofSeconds(30),Duration.ofSeconds(10));}
 HttpAlertTaskClient(String market,String notification,String token,ObjectMapper mapper,Duration executeTimeout,Duration readTimeout){this.market=market;this.notification=notification;this.http=new AlertTaskHttp(token,mapper);this.executeTimeout=executeTimeout;this.readTimeout=readTimeout;}
 public Result prepare(Claim c){require(c,"PREPARE_EVIDENCE");return execute(c,market,"/internal/v1/market/alert-evidence/prepare",Map.of("operationId",c.attemptId(),"instrumentId",c.input().instrumentId(),"rawVersionId",c.input().rawVersionId(),"tradeDate",c.input().tradeDate(),"leaseUntil",c.leaseUntil()),executeTimeout);}
 public Result evaluate(Claim c){require(c,"EVALUATE_RULE");if(c.evidenceId()==null)throw invalid();return execute(c,notification,"/internal/v1/alert-evaluations",Map.of("operationId",c.attemptId(),"ruleId",c.input().ruleId(),"revision",c.input().revision(),"evidenceId",c.evidenceId(),"leaseUntil",c.leaseUntil()),executeTimeout);}
 public Result receipt(Claim c){if(c==null||c.attemptId()==null)throw invalid();boolean prepare="PREPARE_EVIDENCE".equals(c.stage());if(!prepare&&!"EVALUATE_RULE".equals(c.stage()))throw invalid();try{return parse(http.call(prepare?market:notification,(prepare?"/internal/v1/market/alert-evidence/operations/":"/internal/v1/alert-evaluations/operations/")+c.attemptId(),null,readTimeout),c);}catch(AlertTaskHttp.Remote e){if(e.status==404&&"RESOURCE_NOT_FOUND".equals(e.code))throw new MissingReceipt();throw e;}}
 private Result execute(Claim c,String base,String path,Object body,Duration timeout){try{return parse(http.call(base,path,body,timeout),c);}catch(AlertTaskHttp.Remote e){if(com.aistock.scheduler.task.MarketUseTaskErrors.definitive(e.status,e.code))return new Result(c.attemptId(),"FAILED",null,e.code);throw e;}}
 private Result parse(JsonNode envelope,Claim c){if(!"OK".equals(envelope.path("code").asText())||!envelope.path("data").isObject())throw invalid();var n=envelope.path("data");boolean prepare="PREPARE_EVIDENCE".equals(c.stage());String ref=prepare?"evidenceId":"triggerId",err=prepare?"errorCode":"reasonCode";if(!n.has(ref)||!n.has(err)||!n.path("operationId").isTextual()||!c.attemptId().toString().equals(n.path("operationId").textValue())||!n.path("state").isTextual())throw invalid();String state=n.path("state").textValue();UUID reference=null;String error=null;if(!n.path(ref).isNull()){var v=n.path(ref);if(!v.isTextual()||!v.textValue().matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw invalid();reference=UUID.fromString(v.textValue());}if(!n.path(err).isNull()){var v=n.path(err);if(!v.isTextual()||!v.textValue().matches("[A-Z0-9_]{1,64}"))throw invalid();error=v.textValue();}
  if("RUNNING".equals(state)){if(reference!=null||error!=null)throw invalid();}
  else if(prepare){if("AVAILABLE".equals(state)){if(reference==null||error!=null)throw invalid();}else if("FAILED".equals(state)){if(reference!=null||error==null)throw invalid();}else if("SKIPPED_STALE".equals(state)){if(reference!=null||error!=null&&!"ALERT_DATE_NOT_LATEST".equals(error))throw invalid();}else throw invalid();}
  else {if(Set.of("TRIGGERED","ALREADY_TRIGGERED").contains(state)){if(reference==null||error!=null)throw invalid();}else if(Set.of("NOT_MET","SKIPPED_RULE_CHANGED","SKIPPED_NOT_EFFECTIVE","SKIPPED_STALE").contains(state)){if(reference!=null||error!=null)throw invalid();}else if("SKIPPED_INACTIVE".equals(state)){if(reference!=null)throw invalid();}else if(Set.of("FAILED","EVIDENCE_UNAVAILABLE").contains(state)){if(reference!=null||error==null)throw invalid();}else throw invalid();}
  return new Result(c.attemptId(),state,reference,error);
 }
 private void require(Claim c,String stage){if(c==null||!stage.equals(c.stage())||c.attemptId()==null||c.input()==null||c.leaseUntil()==null)throw invalid();}
 private static AlertTaskHttp.Remote invalid(){return AlertTaskHttp.error("ALERT_RECEIPT_INVALID");}
}
